window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d9481d4b96c2cdfa"]={"versions": [{"id": "FIG-d9481d4b96c2cdfa", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches Schichten- und Blockarchitektur-Diagramm (AUTOSAR Adaptive Platform Layered Architecture / Functional Cluster Overview).</li>\n<li><strong>Architektur-Kontext:</strong> Repräsentiert die logische Gliederung der AUTOSAR Adaptive Platform (AP, Release R19-03) zwischen der Hardware-/Virtualisierungsebene und den Benutzerapplikationen.</li>\n<li><strong>Technischer Zweck:</strong> Trennung der Laufzeitumgebung <em>AUTOSAR Runtime for Adaptive Applications (ARA)</em> in prozesslokale Basis-APIs (Foundation Functional Clusters) und prozessübergreifende Dienstinstanzen (Platform Service Functional Clusters) zur Gewährleistung von Modularität, Service-Oriented Architecture (SOA) und echtzeit-/safety-relevantem Betrieb auf POSIX-Betriebssystemen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten (Top-to-Bottom)</p>\n<ol class=\"fig-list\">\n<li><strong>User Applications (ASW Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Applications:</strong> Standard-Anwendungsprozesse.</li>\n<li><strong>Non-PF Services (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsnahe, nicht-plattformgebundene Dienste, die eigene Service-Schnittstellen via SOA bereitstellen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong> Laufzeitumgebung bestehend aus zwei Cluster-Typen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (API-basiert, In-Process-Bibliotheken):</strong></li>\n<li><code>ara::core</code>: Grundlegende Datentypen, Fehlerbehandlung (<code>Result</code>, <code>ErrorCode</code>), Pointer-Abstraktionen und Concurrency-Primitive (<code>Future</code>, <code>Promise</code>).</li>\n<li><code>ara::com</code>: Kommunikationsmanagement mit Protokoll-Bindings für <em>SOME/IP</em>, <em>IPC (local)</em> und <em>DDS</em>.</li>\n<li><code>ara::exec</code>: Execution Management (Prozesslebenszyklus, Scheduling-Konfiguration, State-Transition-Exekution).</li>\n<li><code>ara::per</code>: Persistency (Zugriff auf flüchtigen/nicht-flüchtigen Speicher, Key-Value-Storage, File-Storage).</li>\n<li><code>ara::log</code>: Log and Trace (standardisiertes Logging über DLT-Protokoll oder Konsolenkanäle).</li>\n<li><code>ara::crypto</code>: Cryptography (Schlüsselverwaltung, Signaturprüfung, Verschlüsselungsprimitive).</li>\n<li><code>ara::phm</code>: Platform Health Management (Alive-, Deadline- und Logical-Supervision für funktionale Sicherheit).</li>\n<li><code>ara::iam</code>: Identity and Access Management (Zugriffskontrolle und Privilegienprüfung auf Schnittstellenebene).</li>\n<li><code>ara::tsync</code>: Time Synchronization (Netzwerkweite Zeitsynchronisation, z. B. IEEE 802.1AS / IEEE 1588).</li>\n<li><code>ara::rest</code>: RESTful Communication (Web-basierte Schnittstellenanbindung).</li>\n<li><strong>Platform Service FCs (Service-basiert, eigenständige Systemprozesse/Dämonen via <code>ara::com</code>):</strong></li>\n<li><code>ara::sm service</code>: State Management (Koordination von Maschinen- und Funktionsgruppenzuständen).</li>\n<li><code>ara::diag service</code>: Diagnostics (UDS-basierte Diagnose, ISO 14229 / DoIP).</li>\n<li><code>ara::s2s service</code>: Signal to Service Mapping (Transformation klassischer signalbasierter Buskommunikation in serviceorientierte Schnittstellen).</li>\n<li><code>ara::nm service</code>: Network Management (Zustandsüberwachung des physikalischen Bordnetzes).</li>\n<li><code>ara::ucm service</code>: Update and Config Management (OTA-Software-Updates, Paketinstallation und Firmware-Rollback).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OS Interface & Platform Substrat:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>OS Interface:</strong> POSIX PSE51 (Minimal Realtime Controller Profile nach IEEE 1003.13) / C++ STL.</li>\n<li><strong>Infrastruktur:</strong> (Virtual) Machine / Container / Hardware (Hypervisor, Linux/QNX Microkernel, Target-SoC).</li>\n</ul>\n<p class=\"fig-p\">#### Interaktions- und Schnittstellenmuster</p>\n<ul class=\"fig-list\">\n<li><strong>Direct Library Linking (Foundation FCs):</strong> Adaptive Applications binden Foundation FCs direkt als Shared/Static Libraries über C++-Header ein; Funktionsaufrufe laufen synchron oder asynchron innerhalb des Adressraums der Applikation.</li>\n<li><strong>Service-Oriented Interaction (Service FCs & Non-PF Services):</strong> Kommunikation erfolgt ausschließlich prozessübergreifend über den <code>ara::com</code>-Stack (Proxy/Skeleton-Muster) unter Nutzung von Events, Methods und Fields.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Strukturdiagramm handelt, wird das zugrunde liegende dynamische Interaktionsmodell abgebildet:</p>\n<ol class=\"fig-list\">\n<li><strong>Bootstrap & Initialisierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Host-OS startet; Hardware-Initialisierung.</li>\n<li>Das OS initialisiert <code>ara::exec</code> als Root-Init-Prozess.</li>\n<li><code>ara::exec</code> instanziiert fundamentale Dämonen (Platform Service FCs: <code>ara::sm</code>, <code>ara::diag</code>, <code>ara::ucm</code>) anhand des Manifests (<em>Execution Manifest</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>State Transition & Lifecycle:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::sm service</code> evaluiert Systemzustände und triggert Zustandswechsel über <code>ara::exec</code>.</li>\n<li><code>ara::exec</code> startet/stoppt <code>Adaptive Applications</code> prozessbasiert via POSIX-Aufrufe (<code>fork</code>, <code>execve</code>) und überwacht Ressourcen/Budgets.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Kommunikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Service Offer: Ein Service Provider (<code>ASW::XYZ</code> oder Platform Service) registriert sich via <code>ara::com::Skeleton::OfferService()</code>.</li>\n<li>Service Discovery / Binding: Adaptive Applications lokalisieren Instanzen via <code>ara::com::Proxy::StartFindService()</code> und binden IPC, SOME/IP oder DDS transparent.</li>\n<li>Safety-Überwachung: Laufende Applikationen melden zyklische Checkpoints an <code>ara::phm</code> (ReportCheckpoint). Bei Timeout/Anomalie initiiert <code>ara::phm</code> Gegenmaßnahmen über <code>ara::sm</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>POSIX PSE51 Restriktionen:</strong> Applikationen dürfen keine blockierenden oder nicht echtzeitfähigen POSIX-APIs verwenden. Dynamische Ressourcenallokation nach der Startup-Phase ist im ASIL-Kontext verboten.</li>\n<li><strong>Exception-Free Paradigm (<code>ara::core::Result&lt;T, E&gt;</code>):</strong> AUTOSAR Adaptive (R19-03) erzwingt in sicherheitskritischen Bereichen den Verzicht auf C++-Exceptions. API-Rückgaben sind strikt über monadische <code>ara::core::Result</code>-Typen abzuhandeln.</li>\n<li><strong>Service Definition (ARXML zu C++):</strong></li>\n<li>Schnittstellen zu Service FCs (<code>diag</code>, <code>sm</code>, <code>ucm</code>) und Non-PF Services erfordern standardisierte ARXML-Modellierung (<em>Service Interfaces</em>).</li>\n<li>Proxy- und Skeleton-Klassen werden werkzeuggestützt codegeneriert; manuelle Socket- oder IPC-Programmierung umgeht das IAM-Sicherheitsmodell und ist normativ unzulässig.</li>\n<li><strong>Separation of Concerns:</strong></li>\n<li>Applikationen dürfen nicht direkt auf Hardwaretreiber zugreifen; alle I/O- und Peripheriezugriffe müssen abstrahiert über OS-Treiber bzw. ARA-Cluster (<code>ara::com</code>, <code>ara::per</code>) erfolgen.</li>\n<li>Diagnosefunktionalität darf nicht lokal implementiert werden, sondern muss über die API des <code>ara::diag service</code> an den zentralen Diagnose-Manager delegiert werden.</li>\n</ul>"}, {"id": "FIG-ac6670689654cc08", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches Schichten- und Blockarchitektur-Diagramm (AUTOSAR Adaptive Platform Layered Architecture / Functional Cluster Overview).</li>\n<li><strong>Architektur-Kontext:</strong> Repräsentiert die logische Gliederung der AUTOSAR Adaptive Platform (AP, Release R19-03) zwischen der Hardware-/Virtualisierungsebene und den Benutzerapplikationen.</li>\n<li><strong>Technischer Zweck:</strong> Trennung der Laufzeitumgebung <em>AUTOSAR Runtime for Adaptive Applications (ARA)</em> in prozesslokale Basis-APIs (Foundation Functional Clusters) und prozessübergreifende Dienstinstanzen (Platform Service Functional Clusters) zur Gewährleistung von Modularität, Service-Oriented Architecture (SOA) und echtzeit-/safety-relevantem Betrieb auf POSIX-Betriebssystemen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten (Top-to-Bottom)</p>\n<ol class=\"fig-list\">\n<li><strong>User Applications (ASW Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Applications:</strong> Drei Instanzen von Standard-Anwendungsprozessen.</li>\n<li><strong>Non-PF Services (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsnahe, nicht-plattformgebundene Dienste, die eigene Service-Schnittstellen via SOA bereitstellen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong> Laufzeitumgebung bestehend aus zwei Cluster-Typen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (API-basiert, In-Process-Bibliotheken):</strong></li>\n<li><code>ara::core</code>: Core Types.</li>\n<li><code>ara::com</code>: Kommunikationsmanagement mit Protokoll-Bindings für <em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em> und <em>DDS</em>.</li>\n<li><code>ara::exec</code>: Execution Management (Prozesslebenszyklus, Scheduling-Konfiguration).</li>\n<li><code>ara::per</code>: Persistency (Zugriff auf flüchtigen/nicht-flüchtigen Speicher).</li>\n<li><code>ara::log</code>: Log and Trace.</li>\n<li><code>ara::crypto</code>: Cryptography.</li>\n<li><code>ara::phm</code>: Platform Health Management (Alive-, Deadline- und Logical-Supervision).</li>\n<li><code>ara::iam</code>: Identity and Access Management.</li>\n<li><code>ara::tsync</code>: Time Synchronization.</li>\n<li><code>ara::rest</code>: RESTful Communication.</li>\n<li><code>ara::diag</code>: Diagnostics (standardisierte Diagnosefunktionalität als Foundation FC).</li>\n<li><strong>Platform Service FCs (Service-basiert, eigenständige Systemprozesse/Dämonen via <code>ara::com</code>):</strong></li>\n<li><code>ara::sm service</code>: State Management.</li>\n<li><code>ara::ucm service</code>: Update and Config Management.</li>\n<li><code>ara::nm service</code>: Network Management.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OS Interface & Platform Substrat:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>OS Interface:</strong> POSIX PSE51 / C++ STL Operating System Interface.</li>\n<li><strong>Infrastruktur:</strong> (Virtual) Machine / Container / Hardware.</li>\n</ul>\n<p class=\"fig-p\">#### Interaktions- und Schnittstellenmuster</p>\n<ul class=\"fig-list\">\n<li><strong>Direct Library Linking (Foundation FCs):</strong> Adaptive Applications binden Foundation FCs direkt als Shared/Static Libraries über C++-Sprach-APIs an.</li>\n<li><strong>Service-Oriented Inter-Process Communication (Platform Services):</strong> Platform Services stellen über <code>ara::com</code> funktionale Schnittstellen bereit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basisinfrastruktur startet das Betriebssystem und stellt das POSIX PSE51 / C++ STL OS Interface bereit.</li>\n<li><code>ara::exec</code> initialisiert die Plattform-Dienste (<code>ara::sm</code>, <code>ara::ucm</code>, <code>ara::nm</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Kommunikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Adaptive Applications greifen lokal über In-Process C++-APIs auf Foundation FCs zu (einschließlich <code>ara::diag</code>, <code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::phm</code>, etc.).</li>\n<li>Prozessübergreifender und netzwerkweiter Datenaustausch erfolgt über <code>ara::com</code> über die Protokoll-Bindings <em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em> oder <em>DDS</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Update-Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::sm service</code> koordiniert System- und Funktionsgruppenzustände.</li>\n<li><code>ara::ucm service</code> steuert Paketverwaltung, Installation und Software-Updates.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>POSIX PSE51 Restriktionen:</strong> Applikationen dürfen keine blockierenden oder nicht echtzeitfähigen POSIX-APIs verwenden. Dynamische Ressourcenallokation nach der Startup-Phase ist im ASIL-Kontext verboten.</li>\n<li><strong>Exception-Free Paradigm (<code>ara::core::Result&lt;T, E&gt;</code>):</strong> AUTOSAR Adaptive (R19-03) erzwingt in sicherheitskritischen Bereichen den Verzicht auf C++-Exceptions. API-Rückgaben sind strikt über monadische <code>ara::core::Result</code>-Typen abzuhandeln.</li>\n<li><strong>Service Definition (ARXML zu C++):</strong></li>\n<li>Schnittstellen zu Service FCs (<code>diag</code>, <code>sm</code>, <code>ucm</code>) und Non-PF Services erfordern standardisierte ARXML-Modellierung (<em>Service Interfaces</em>).</li>\n<li>Proxy- und Skeleton-Klassen werden werkzeuggestützt codegeneriert; manuelle Socket- oder IPC-Programmierung umgeht das IAM-Sicherheitsmodell und ist normativ unzulässig.</li>\n<li><strong>Separation of Concerns:</strong></li>\n<li>Applikationen dürfen nicht direkt auf Hardwaretreiber zugreifen; alle I/O- und Peripheriezugriffe müssen abstrahiert über OS-Treiber bzw. ARA-Cluster (<code>ara::com</code>, <code>ara::per</code>) erfolgen.</li>\n<li>Diagnosefunktionalität darf nicht lokal implementiert werden, sondern muss über die API des <code>ara::diag service</code> an den zentralen Diagnose-Manager delegiert werden.</li>\n</ul>"}, {"id": "FIG-9a536a45e9e16c64", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches Schichten- und Blockarchitektur-Diagramm (AUTOSAR Adaptive Platform Layered Architecture / Functional Cluster Overview).</li>\n<li><strong>Architektur-Kontext:</strong> Repräsentiert die logische Gliederung der AUTOSAR Adaptive Platform (AP, Release R19-03) zwischen der Hardware-/Virtualisierungsebene und den Benutzerapplikationen.</li>\n<li><strong>Technischer Zweck:</strong> Trennung der Laufzeitumgebung <em>AUTOSAR Runtime for Adaptive Applications (ARA)</em> in prozesslokale Basis-APIs (Foundation Functional Clusters) und prozessübergreifende Dienstinstanzen (Platform Service Functional Clusters) zur Gewährleistung von Modularität, Service-Oriented Architecture (SOA) und echtzeit-/safety-relevantem Betrieb auf POSIX-Betriebssystemen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten (Top-to-Bottom)</p>\n<ol class=\"fig-list\">\n<li><strong>User Applications (ASW Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Applications:</strong> Drei Instanzen von Standard-Anwendungsprozessen.</li>\n<li><strong>Non-PF Services (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsnahe, nicht-plattformgebundene Dienste, die eigene Service-Schnittstellen via SOA bereitstellen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong> Laufzeitumgebung bestehend aus zwei Cluster-Typen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (API-basiert, In-Process-Bibliotheken):</strong></li>\n<li><code>ara::core</code>: Core.</li>\n<li><code>ara::com</code>: Kommunikationsmanagement mit Protokoll-Bindings für <em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em> und <em>DDS</em>.</li>\n<li><code>ara::exec</code>: Execution Management (Prozesslebenszyklus, Scheduling-Konfiguration).</li>\n<li><code>ara::per</code>: Persistency (Zugriff auf flüchtigen/nicht-flüchtigen Speicher).</li>\n<li><code>ara::log</code>: Log and Trace.</li>\n<li><code>ara::crypto</code>: Cryptography.</li>\n<li><code>ara::phm</code>: Platform Health Management (Alive-, Deadline- und Logical-Supervision).</li>\n<li><code>ara::iam</code>: Identity and Access Management.</li>\n<li><code>ara::tsync</code>: Time Synchronization.</li>\n<li><code>ara::rest</code>: REST.</li>\n<li><code>ara::diag</code>: Diagnostics (standardisierte Diagnosefunktionalität als Foundation FC).</li>\n<li><strong>Platform Service FCs (Service-basiert, eigenständige Systemprozesse/Dämonen via <code>ara::com</code>):</strong></li>\n<li><code>ara::sm service</code>: State Management.</li>\n<li><code>ara::ucm service</code>: Update and Config Management.</li>\n<li><code>ara::nm service</code>: Network Management.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OS Interface & Platform Substrat:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>OS Interface:</strong> POSIX PSE51 / C++ STL Operating System Interface.</li>\n<li><strong>Infrastruktur:</strong> (Virtual) Machine / Container / Hardware.</li>\n</ul>\n<p class=\"fig-p\">#### Interaktions- und Schnittstellenmuster</p>\n<ul class=\"fig-list\">\n<li><strong>Direct Library Linking (Foundation FCs):</strong> Adaptive Applications binden Foundation FCs direkt als Shared/Static Libraries über C++-Sprach-APIs an.</li>\n<li><strong>Service-Oriented Inter-Process Communication (Platform Services):</strong> Platform Services stellen über <code>ara::com</code> funktionale Schnittstellen bereit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basisinfrastruktur startet das Betriebssystem und stellt das POSIX PSE51 / C++ STL OS Interface bereit.</li>\n<li><code>ara::exec</code> initialisiert die Plattform-Dienste (<code>ara::sm</code>, <code>ara::ucm</code>, <code>ara::nm</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Kommunikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Adaptive Applications greifen lokal über In-Process C++-APIs auf Foundation FCs zu (einschließlich <code>ara::diag</code>, <code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::phm</code>, etc.).</li>\n<li>Prozessübergreifender und netzwerkweiter Datenaustausch erfolgt über <code>ara::com</code> über die Protokoll-Bindings <em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em> oder <em>DDS</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Update-Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::sm service</code> koordiniert System- und Funktionsgruppenzustände.</li>\n<li><code>ara::ucm service</code> steuert Paketverwaltung, Installation und Software-Updates.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>POSIX PSE51 Restriktionen:</strong> Applikationen dürfen keine blockierenden oder nicht echtzeitfähigen POSIX-APIs verwenden. Dynamische Ressourcenallokation nach der Startup-Phase ist im ASIL-Kontext verboten.</li>\n<li><strong>Exception-Free Paradigm (<code>ara::core::Result&lt;T, E&gt;</code>):</strong> AUTOSAR Adaptive (R19-03) erzwingt in sicherheitskritischen Bereichen den Verzicht auf C++-Exceptions. API-Rückgaben sind strikt über monadische <code>ara::core::Result</code>-Typen abzuhandeln.</li>\n<li><strong>Service Definition (ARXML zu C++):</strong></li>\n<li>Schnittstellen zu Service FCs (<code>diag</code>, <code>sm</code>, <code>ucm</code>) und Non-PF Services erfordern standardisierte ARXML-Modellierung (<em>Service Interfaces</em>).</li>\n<li>Proxy- und Skeleton-Klassen werden werkzeuggestützt codegeneriert; manuelle Socket- oder IPC-Programmierung umgeht das IAM-Sicherheitsmodell und ist normativ unzulässig.</li>\n<li><strong>Separation of Concerns:</strong></li>\n<li>Applikationen dürfen nicht direkt auf Hardwaretreiber zugreifen; alle I/O- und Peripheriezugriffe müssen abstrahiert über OS-Treiber bzw. ARA-Cluster (<code>ara::com</code>, <code>ara::per</code>) erfolgen.</li>\n<li>Diagnosefunktionalität darf nicht lokal implementiert werden, sondern muss über die API des <code>ara::diag service</code> an den zentralen Diagnose-Manager delegiert werden.</li>\n</ul>"}, {"id": "FIG-0094cd7c92aedcd6", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Statisches Schichten- und Blockarchitektur-Diagramm (AUTOSAR Adaptive Platform Layered Architecture / Functional Cluster Overview).</li>\n<li><strong>Architektur-Kontext:</strong> Repräsentiert die logische Gliederung der AUTOSAR Adaptive Platform (AP, Release R19-03) zwischen der Hardware-/Virtualisierungsebene und den Benutzerapplikationen.</li>\n<li><strong>Technischer Zweck:</strong> Trennung der Laufzeitumgebung <em>AUTOSAR Runtime for Adaptive Applications (ARA)</em> in prozesslokale Basis-APIs (Foundation Functional Clusters) und prozessübergreifende Dienstinstanzen (Platform Service Functional Clusters) zur Gewährleistung von Modularität, Service-Oriented Architecture (SOA) und echtzeit-/safety-relevantem Betrieb auf POSIX-Betriebssystemen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten (Top-to-Bottom)</p>\n<ol class=\"fig-list\">\n<li><strong>User Applications (ASW Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Adaptive Applications:</strong> Drei Instanzen von Standard-Anwendungsprozessen.</li>\n<li><strong>Non-PF Services (<code>ASW::XYZ</code>, <code>ASW::ABC</code>):</strong> Anwendungsnahe, nicht-plattformgebundene Dienste, die eigene Service-Schnittstellen via SOA bereitstellen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>AUTOSAR Runtime for Adaptive Applications (ARA):</strong> Laufzeitumgebung bestehend aus zwei Cluster-Typen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Platform Foundation FCs (API-basiert, In-Process-Bibliotheken):</strong></li>\n<li><code>ara::core</code>: Core.</li>\n<li><code>ara::com</code>: Kommunikationsmanagement mit Protokoll-Bindings für <em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em> und <em>DDS</em>.</li>\n<li><code>ara::idsm</code>: Intrusion Detection System Manager.</li>\n<li><code>ara::exec</code>: Execution Management (Prozesslebenszyklus, Scheduling-Konfiguration).</li>\n<li><code>ara::per</code>: Persistency (Zugriff auf flüchtigen/nicht-flüchtigen Speicher).</li>\n<li><code>ara::log</code>: Log and Trace.</li>\n<li><code>ara::crypto</code>: Cryptography.</li>\n<li><code>ara::phm</code>: Platform Health Management (Alive-, Deadline- und Logical-Supervision).</li>\n<li><code>ara::iam</code>: Identity and Access Management.</li>\n<li><code>ara::tsync</code>: Time Synchronization.</li>\n<li><code>ara::diag</code>: Diagnostics (standardisierte Diagnosefunktionalität als Foundation FC).</li>\n<li><strong>Platform Service FCs (Service-basiert, eigenständige Systemprozesse/Dämonen via <code>ara::com</code>):</strong></li>\n<li><code>ara::sm service</code>: State Management.</li>\n<li><code>ara::ucm service</code>: Update and Config Management.</li>\n<li><code>ara::nm service</code>: Network Management.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>OS Interface & Platform Substrat:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>OS Interface:</strong> POSIX PSE51 / C++ STL Operating System Interface.</li>\n<li><strong>Infrastruktur:</strong> (Virtual) Machine / Container / Hardware.</li>\n</ul>\n<p class=\"fig-p\">#### Interaktions- und Schnittstellenmuster</p>\n<ul class=\"fig-list\">\n<li><strong>Direct Library Linking (Foundation FCs):</strong> Adaptive Applications binden Foundation FCs direkt als Shared/Static Libraries über C++-Sprach-APIs an.</li>\n<li><strong>Service-Oriented Inter-Process Communication (Platform Services):</strong> Platform Services stellen über <code>ara::com</code> funktionale Schnittstellen bereit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung & Hochlauf:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basisinfrastruktur startet das Betriebssystem und stellt das POSIX PSE51 / C++ STL OS Interface bereit.</li>\n<li><code>ara::exec</code> initialisiert die Plattform-Dienste (<code>ara::sm</code>, <code>ara::ucm</code>, <code>ara::nm</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Kommunikation & Security-Monitoring:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Adaptive Applications greifen lokal über In-Process C++-APIs auf Foundation FCs zu (einschließlich <code>ara::diag</code>, <code>ara::core</code>, <code>ara::per</code>, <code>ara::crypto</code>, <code>ara::phm</code>, etc.).</li>\n<li>Sicherheitsrelevante Ereignisse und Anomalien werden über <code>ara::idsm</code> erfasst und überwacht.</li>\n<li>Prozessübergreifender und netzwerkweiter Datenaustausch erfolgt über <code>ara::com</code> über die Protokoll-Bindings <em>IPC</em>, <em>Signal PDU</em>, <em>SOME/IP</em> oder <em>DDS</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zustands- und Update-Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ara::sm service</code> koordiniert System- und Funktionsgruppenzustände.</li>\n<li><code>ara::ucm service</code> steuert Paketverwaltung, Installation und Software-Updates.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>POSIX PSE51 Restriktionen:</strong> Applikationen dürfen keine blockierenden oder nicht echtzeitfähigen POSIX-APIs verwenden. Dynamische Ressourcenallokation nach der Startup-Phase ist im ASIL-Kontext verboten.</li>\n<li><strong>Exception-Free Paradigm (<code>ara::core::Result&lt;T, E&gt;</code>):</strong> AUTOSAR Adaptive (R19-03) erzwingt in sicherheitskritischen Bereichen den Verzicht auf C++-Exceptions. API-Rückgaben sind strikt über monadische <code>ara::core::Result</code>-Typen abzuhandeln.</li>\n<li><strong>Service Definition (ARXML zu C++):</strong></li>\n<li>Schnittstellen zu Service FCs (<code>diag</code>, <code>sm</code>, <code>ucm</code>) und Non-PF Services erfordern standardisierte ARXML-Modellierung (<em>Service Interfaces</em>).</li>\n<li>Proxy- und Skeleton-Klassen werden werkzeuggestützt codegeneriert; manuelle Socket- oder IPC-Programmierung umgeht das IAM-Sicherheitsmodell und ist normativ unzulässig.</li>\n<li><strong>Separation of Concerns:</strong></li>\n<li>Applikationen dürfen nicht direkt auf Hardwaretreiber zugreifen; alle I/O- und Peripheriezugriffe müssen abstrahiert über OS-Treiber bzw. ARA-Cluster (<code>ara::com</code>, <code>ara::per</code>) erfolgen.</li>\n<li>Diagnosefunktionalität darf nicht lokal implementiert werden, sondern muss über die API des <code>ara::diag service</code> an den zentralen Diagnose-Manager delegiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-d9481d4b96c2cdfa", "to": "FIG-ac6670689654cc08", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In <em>User Applications</em>: Reduzierung von 4 auf 3 generische Instanzen von <code>Adaptive Application</code>.</li>\n<li>In <em>ARA Platform Foundation FCs</em>:</li>\n<li>Protokoll-Bindings unter <code>ara::com</code>: Ergänzung von <code>Signal PDU</code> neben <code>SOME/IP</code>, <code>IPC</code> und <code>DDS</code> (Reihenfolge neu: <code>IPC</code>, <code>Signal PDU</code>, <code>SOME/IP</code>, <code>DDS</code>; <code>(local)</code> bei IPC entfallen).</li>\n<li>Umgruppierung und Layout-Änderung der Foundation FCs (neu 4 Spalten): <code>ara::diag</code> wechselt von Platform Service FC zu Platform Foundation FC (Beschriftung <code>ara::diag Diagnostics</code> mit blauem Header statt grau).</li>\n<li>Neuanordnung: <code>ara::crypto Cryptography</code> ist nun in Zeile 3 platziert; <code>ara::log Log and Trace</code> in Zeile 2.</li>\n<li>In <em>ARA Platform Service FCs</em>:</li>\n<li><code>ara::s2s service</code> (Signal to Service Mapping) ist entfallen.</li>\n<li>Spaltenanordnung der verbleibenden Service FCs komprimiert auf eine Spalte rechts: <code>ara::sm service State Management</code>, <code>ara::ucm service Update and Config Management</code>, <code>ara::nm service Network Management</code>.</li>\n</ul>"}, {"from": "FIG-ac6670689654cc08", "to": "FIG-9a536a45e9e16c64", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Block <code>ara::core Core Types</code> umbenannt in <code>ara::core Core</code>.</li>\n<li>Block <code>ara::rest RESTful</code> umbenannt in <code>ara::rest REST</code>.</li>\n</ul>"}, {"from": "FIG-9a536a45e9e16c64", "to": "FIG-0094cd7c92aedcd6", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Block <code>ara::rest REST</code> entfällt.</li>\n<li>Block <code>ara::idsm Intrusion Detection System Manager</code> als Platform Foundation FC neu hinzugefügt (an der Position des vormaligen <code>ara::rest</code>).</li>\n</ul>"}]};
